package com.axonbase.core.cluster;import org.junit.jupiter.api.Test;import java.nio.file.*;import java.net.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class TcpRaftCommitCoordinatorTest{@Test void confirmaPorQuorumTcp()throws Exception{var a=Files.createTempDirectory("a");var b=Files.createTempDirectory("b");try(var s1=new TcpRaftServer(0,new RaftNode("n2",a)::handle);var s2=new TcpRaftServer(0,new RaftNode("n3",b)::handle)){var c=new TcpRaftCommitCoordinator("g","n1",List.of(new InetSocketAddress("127.0.0.1",s1.port()),new InetSocketAddress("127.0.0.1",s2.port())));assertEquals(1,c.confirm("n1",new CommittedBatch("t",Map.of("x",new byte[]{1}),Set.of())));}}
@Test void rejeitaSemMaioriaTcp(){var c=new TcpRaftCommitCoordinator("g","n1",List.of(new InetSocketAddress("127.0.0.1",9),new InetSocketAddress("127.0.0.1",10)));assertThrows(QuorumUnavailableException.class,()->c.confirm("n1",new CommittedBatch("t",Map.of(),Set.of())));}}
